SET FOREIGN_KEY_CHECKS = 0;

-- ── UserProfile ──────────────────────────────────────────────
TRUNCATE TABLE userprofile;

-- ── UserAccount ──────────────────────────────────────────────
TRUNCATE TABLE useraccount;

-- ── Category ────────────────────────────────────────────────
TRUNCATE TABLE category;

-- ── Activity ────────────────────────────────────────────────
TRUNCATE TABLE activity;

-- ── Favourite ───────────────────────────────────────────────
TRUNCATE TABLE favourite;

-- ── Donation ────────────────────────────────────────────────
TRUNCATE TABLE donation;

SET FOREIGN_KEY_CHECKS = 1;

-- ── Verify record counts ──────────────────────────────────────
SELECT 'userprofile' as table_name, COUNT(*) as records FROM userprofile
UNION ALL SELECT 'useraccount', COUNT(*) FROM useraccount
UNION ALL SELECT 'category', COUNT(*) FROM category
UNION ALL SELECT 'activity', COUNT(*) FROM activity
UNION ALL SELECT 'favourite', COUNT(*) FROM favourite
UNION ALL SELECT 'donation', COUNT(*) FROM donation;